package com.threatstream.detection;
import java.time.*; import java.util.*; import org.springframework.stereotype.Service;
@Service class NetworkDetectionEngine { private final NetworkEventValidator validator; private final EventDeduplicator dedup; private final AlertPublisher publisher; private final NetworkDetectionProperties p; private final AlertFactory factory; private final Map<String,Deque<NetworkEvent>> ports=new HashMap<>(),rates=new HashMap<>(),distributed=new HashMap<>(); private final Map<String,Instant> cooldowns=new HashMap<>(); NetworkDetectionEngine(NetworkEventValidator v,EventDeduplicator d,AlertPublisher a,NetworkDetectionProperties p,AlertFactory f){validator=v;dedup=d;publisher=a;this.p=p;factory=f;}
 synchronized void process(NetworkEvent e){validator.validate(e);if(!dedup.first(e.eventId()))return;portScan(e);dos(e);ddos(e);}
 private void portScan(NetworkEvent e){String k=e.sourceIp()+"|"+e.destinationIp();Deque<NetworkEvent> q=window(ports,k,e,p.portScan().window());long count=q.stream().map(NetworkEvent::destinationPort).distinct().count();if(count>=p.portScan().threshold()&&ready("port|"+k,e.timestamp(),p.portScan().cooldown()))publisher.publish(factory.create("NETWORK_PORT_SCAN","PORT_SCAN","HIGH",e.sourceIp(),e.timestamp(),q.peek().timestamp(),Map.of("distinctDestinationPorts",count,"targetIp",e.destinationIp(),"windowSeconds",p.portScan().window().toSeconds())));}
 private void dos(NetworkEvent e){if(e.flowBytesPerSecond()==null&&e.flowPacketsPerSecond()==null)return;String k=e.sourceIp()+"|"+e.destinationIp();Deque<NetworkEvent> q=window(rates,k,e,p.dos().window());double bytes=q.stream().map(NetworkEvent::flowBytesPerSecond).filter(Objects::nonNull).mapToDouble(Double::doubleValue).sum();double packets=q.stream().map(NetworkEvent::flowPacketsPerSecond).filter(Objects::nonNull).mapToDouble(Double::doubleValue).sum();if(bytes>=p.dos().bytesPerSecond()||packets>=p.dos().packetsPerSecond())if(ready("dos|"+k,e.timestamp(),p.dos().cooldown()))publisher.publish(factory.create("NETWORK_DOS","DOS_SUSPECTED","HIGH",e.sourceIp(),e.timestamp(),q.peek().timestamp(),Map.of("aggregateBytesPerSecond",bytes,"aggregatePacketsPerSecond",packets,"targetIp",e.destinationIp(),"windowSeconds",p.dos().window().toSeconds())));}
 private void ddos(NetworkEvent e){if(e.flowBytesPerSecond()==null)return;String k=e.destinationIp();Deque<NetworkEvent> q=window(distributed,k,e,p.ddos().window());double bytes=q.stream().map(NetworkEvent::flowBytesPerSecond).filter(Objects::nonNull).mapToDouble(Double::doubleValue).sum();long sources=q.stream().map(NetworkEvent::sourceIp).distinct().count();if(bytes>=p.ddos().bytesPerSecond()&&sources>=p.ddos().sources()&&ready("ddos|"+k,e.timestamp(),p.ddos().cooldown()))publisher.publish(factory.create("NETWORK_DDOS","DDOS_SUSPECTED","CRITICAL",e.sourceIp(),e.timestamp(),q.peek().timestamp(),Map.of("distinctSources",sources,"aggregateBytesPerSecond",bytes,"targetIp",e.destinationIp(),"windowSeconds",p.ddos().window().toSeconds())));}
 private Deque<NetworkEvent> window(Map<String,Deque<NetworkEvent>> state,String key,NetworkEvent e,Duration duration){if(state.size()>p.maxTrackedKeys())state.clear();Deque<NetworkEvent> q=state.computeIfAbsent(key,x->new ArrayDeque<>());q.add(e);Instant cutoff=e.timestamp().minus(duration);q.removeIf(x->x.timestamp().isBefore(cutoff));return q;}private boolean ready(String key,Instant now,Duration cooldown){Instant last=cooldowns.get(key);if(last!=null&&!last.plus(cooldown).isBefore(now))return false;cooldowns.entrySet().removeIf(x->x.getValue().plus(cooldown).isBefore(now));cooldowns.put(key,now);return true;} }
